	"coachPage.consentBulletMessages": "Les messages que vous envoyez au coach, y compris tout ce que vous écrivez sur votre santé ou vos blessures ; n'y mettez donc rien que vous préféreriez ne pas partager.",
	"coachPage.consentBulletRoutes": "Pour l'assistant d'itinéraires : le nom et les caractéristiques du parcours, la demande que vous saisissez et une indication de lieu approximative — jamais vos coordonnées précises.",
	"coachPage.consentBulletPlanRequest": "Pour l'assistant de plan : la description du plan que vous saisissez (course visée, temps visés et récents, nombre de jours où vous pouvez vous entraîner), uniquement pour remplir les paramètres du plan — le plan lui-même est créé par le générateur de Threkir, pas par l'IA.",
	"coachPage.consentBulletPlanEdit": "Pour les ajustements de plan par IA : les prochaines séances du plan que vous modifiez (dates, types et distances) et la modification que vous saisissez, uniquement pour proposer des changements que vous vérifiez avant tout enregistrement — l'IA ne peut ni ajouter de séances ni fixer d'allures.",
	"coachPage.consentBulletPlatePhoto": "Pour la saisie par photo de repas : la photo de votre repas que vous choisissez, envoyée uniquement pour estimer ce qu'il y a dans l'assiette. La position et les données de l'appareil photo sont retirées avant l'envoi, Threkir ne conserve pas la photo et rien n'est enregistré tant que vous n'avez pas vérifié et enregistré.",
	"coachPage.consentBulletCoachAssist": "Pour les coachs qui utilisent l'assistant de coaching : ce que vous lui demandez et, uniquement pour un athlète qui l'a autorisé sur votre lien de coaching, ses messages récents avec vous, son plan et ses prochaines séances, et ses courses récentes, utilisés uniquement pour rédiger un message visible par vous seul. Vous le modifiez et l'envoyez vous-même, et il est marqué comme assisté par IA.",
	"coachPage.consentBulletCoachSettings": "Vos unités de distance, votre fréquence cardiaque au repos et maximale (uniquement si vous avez donné votre consentement aux données de santé), votre objectif de distance hebdomadaire et la personnalité du coach que vous avez choisie.",
	"coachPage.consentBulletLifts": "Un résumé de vos séances de musculation les plus récentes : la date, le nom de la séance, le nombre d'exercices et de séries, et le poids total soulevé.",
	"coachPage.consentBulletNutrition": "Uniquement si vous avez donné votre consentement aux données de santé : un résumé sur 7 jours de votre journal alimentaire (jours renseignés et moyennes des calories, protéines, glucides et lipides), jamais les repas individuels.",
	"coachPage.consentTermsPrefix": "Les éléments marqués « uniquement si vous avez donné votre consentement aux données de santé » sont des données de santé : en acceptant, vous consentez explicitement à ce qu'ils soient envoyés à Anthropic pour ces fonctionnalités. Anthropic traite les données pour le compte de Threkir selon ses conditions de traitement des données, n'entraîne pas ses modèles sur celles-ci et les supprime dans un délai de 30 jours (plus longtemps uniquement pour les contenus signalés par ses systèmes de sécurité). Vous pouvez retirer ce consentement à tout moment sur votre page Compte ; cela empêche tout envoi ultérieur, mais n'annule pas ce qui a déjà été envoyé. Tous les détails, y compris les garanties encadrant le transfert, figurent dans notre ",
	"coachPage.consentPrivacyLink": "politique de confidentialité",
