	"dash.readinessFromLoadOnly": "Calculé uniquement à partir de votre charge d'entraînement. Le sommeil et la fréquence cardiaque au repos ne sont pas encore pris en compte.",
	"dash.vo2maxTooltip": "VO₂ max — votre moteur aérobie : la quantité d'oxygène que votre corps peut utiliser par minute. Plus c'est élevé, plus vous êtes en forme.",
	"metric.vo2max.label": "VO₂ max",
	"metric.ageGrade.label": "Indice d'âge",
	"metric.ageGrade.definition": "Indice d'âge — votre temps comparé à la meilleure performance pour votre âge et votre sexe. Environ 60 % correspond à un bon coureur local ; 80 %, au niveau national.",
	"metric.vert.label": "D+",
	"metric.vert.definition": "D+ — la hauteur totale que vous avez grimpée, en additionnant toutes les montées.",
	"metric.trimp.label": "TRIMP",
	"metric.trimp.definition": "TRIMP (impulsion d'entraînement) — un score de la difficulté d'une course, calculé à partir de sa durée et de votre fréquence cardiaque.",
	"metric.riegel.label": "formule de Riegel",
	"metric.riegel.definition": "Formule de Riegel — une méthode courante pour prédire votre temps sur une distance à partir d'un temps réalisé sur une autre.",
	"metric.vdot.label": "VDOT",
	"metric.vdot.definition": "VDOT — un score de forme issu de la formule de l'entraîneur Jack Daniels, calculé à partir d'un temps de course récent. Plus il est élevé, plus vous êtes en forme, et vos allures d'entraînement en découlent.",
	"metric.distanceBanked.definition": "Distance accumulée — la part de la distance totale de ce plan que vous avez déjà courue.",
	"metric.planPhases.label": "Phases d'entraînement",
	"metric.planPhases.definition": "Phases d'entraînement — Base installe la course facile, Développement ajoute des séances plus dures, Pic est le bloc le plus exigeant, Affûtage allège pour que vous arriviez frais, et Semaine de course, ce sont les derniers jours faciles avant la course.",
	"metric.e1rm.definition": "1RM (répétition maximale) — la charge la plus lourde que vous pourriez soulever une seule fois. Le 1RM estimé est calculé à partir du poids et des répétitions d'une de vos séries, sans jamais avoir à le tester.",
	"metric.e1rm.inline": "répétition maximale estimée (1RM)",
	"metric.rpe.definition": "RPE (effort perçu) — la difficulté ressentie d'une série, de 1 à 10. Un 10 veut dire que vous n'auriez pas pu faire une répétition de plus.",
	"metric.kom.label": "KOM/QOM",
	"metric.kom.definition": "KOM/QOM (Roi / Reine de la montagne) — la couronne du meilleur temps sur un segment, une pour les hommes et une pour les femmes.",
	"dash.ctlTooltip": "Forme (CTL) — votre charge d'entraînement glissante sur 42 jours. Se construit lentement ; c'est votre base d'endurance.",
	"dash.ctlLabel": "CTL (forme)",
	"dash.ctlUnit": "charge sur 42 jours",
	"dash.atlTooltip": "Fatigue (ATL) — votre charge des 7 derniers jours. Monte vite après les séances dures et baisse avec le repos.",
