	"prefs.hrMedicationSetMaxHr": "Indiquez ci-dessus une fréquence cardiaque max mesurée, lors d'un effort intense ou d'un test, pour que vos zones vous correspondent.",
	"prefs.demographicsHeading": "Données démographiques et corporelles",
	"prefs.demographicsDesc": "Facultatif. Le genre et la tranche d'âge alimentent les filtres des classements de segments (les mêmes catégories que Strava) ; la taille et le poids alimentent vos objectifs nutritionnels de calories et de macros. Laissez un champ vide pour renoncer à cet usage.",
	"prefs.demographicsConsentNotice": "Ces champs sont des données de santé au sens de l'art. 9 du RGPD. Nous ne les traitons qu'avec votre consentement explicite ci-dessous, et uniquement pour les finalités qu'il indique. Consultez notre",
	"prefs.privacyPolicyLink": "politique de confidentialité",
	"prefs.demographicsConsentNoticeTail": " pour connaître l'ensemble des finalités, la durée de conservation et vos droits de retrait.",
	"prefs.demographicsConsent": "Je consens à ce que Threkir conserve mon genre, ma taille, mon historique de poids, toute information sur le cycle ou la grossesse, la fréquence cardiaque enregistrée avec mes activités, les cibles de fréquence cardiaque de mes plans, mon réglage relatif aux médicaments qui modifient ma fréquence cardiaque et mon journal alimentaire, et les utilise avec ma date de naissance en tant que données de santé (art. 9, par. 2, point a, du RGPD) pour personnaliser mon entraînement et mes objectifs nutritionnels et me placer dans les classements de segments par genre et par tranche d'âge. Je peux retirer ce consentement à tout moment.",
