	"prefs.weight": "Poids",
	"prefs.consentRecordedOn": "Consentement enregistré le {date}. En décochant la case ci-dessus puis en enregistrant, vous retirez votre consentement (art. 7, par. 3, du RGPD), ce qui efface votre genre, votre taille, votre historique de poids, toute information sur le cycle ou la grossesse, la fréquence cardiaque enregistrée avec vos activités, les cibles de fréquence cardiaque de vos plans, votre réglage relatif aux médicaments qui modifient votre fréquence cardiaque et votre journal alimentaire. Vos activités elles-mêmes sont conservées, et votre date de naissance reste enregistrée pour indiquer votre âge, mais n'est plus utilisée en tant que donnée de santé.",
